import json,numpy as np
p=np.load('p_d.npy')
XL,mq,kpv,kiv,mp,TPf,TQf,TVf=[float(x) for x in p]
sub={
 "params":{"XL":XL,"mq":mq,"kpv":kpv,"kiv":kiv,"mp":mp,"TPf":TPf,"TQf":TQf,"TVf":TVf,"w0":2*np.pi*60},
 "defs":{
   "Vcmd":"Vset + mq*Q0 - mq*Qm",
   "E0":"sqrt((Q0*XL+V0**2)**2+(P0*XL)**2)/V0",
   "x":"de - theta",
   "Eraw":"kpv*(Vcmd-Vm)+xv",
   "E":"Min(Max(Eraw,0),1.25)"
 },
 "states":{
   "Pm":{"rhs":"(P-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "de":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(P0*XL,Q0*XL+V0**2)"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"E0"}
 },
 "outputs":{"P":"V*E*sin(x)/XL","Q":"V*(E*cos(x)-V)/XL"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(open('tools/check_submission.py').read()[:1500])

